// Whiteout Survival building upgrade tables.
//
// Scraped from whiteoutsurvival.wiki /buildings/ pages, with each Fire Crystal page
// merged into its base building so every ladder runs continuously:
// 1..30, then 30-1..30-4, FC 1, FC 1-1..FC 1-4, FC 2, and so on to FC 10.
// Raising one full Fire Crystal level therefore takes five steps, which is how the
// game does it.
//
// These drive the upgrade optimiser: cost and time say what an upgrade demands,
// power says what it is worth, and prereqs say whether it is legal yet.
//
// EDIT FREELY: if the game changes a value, fix it here. Nothing in the optimiser
// hardcodes a number.
//
// CAVEAT 1: the wiki renders resource costs as unlabelled icons, so the mapping of
// meat/wood/coal/iron and of the two Fire Crystal currencies is inferred from column
// order and magnitude. Times, power and prerequisites are read directly.
//
// CAVEAT 3: Steel is not used by building upgrades. Research Center tech is in
// whiteoutResearch.ts and War Academy tech is in whiteoutWarAcademy.ts. This
// comment used to say both lived in whiteoutResearch.ts, which was wrong and
// hid the fact that the War Academy tree was missing from the data entirely.
//
// CAVEAT 2: construction times here are the game's base values. Real build time
// depends on the player's stacked speed buffs (Agnes expert, island buildings,
// President and Chief Order buffs, pet skills, facilities, Tooling Up research,
// Zinman, VIP level). The optimiser applies the single speed buff percentage the
// player enters, which is where all of that gets summarised.

export type WhiteoutResource =
  | 'meat'
  | 'wood'
  | 'coal'
  | 'iron'
  | 'steel'
  | 'fireCrystal'
  | 'refinedFireCrystal'
  | 'fireCrystalShard';

export const WHITEOUT_RESOURCES: WhiteoutResource[] = [
  'meat',
  'wood',
  'coal',
  'iron',
  'steel',
  'fireCrystal',
  'refinedFireCrystal',
  'fireCrystalShard',
];

export const RESOURCE_LABELS: Record<WhiteoutResource, string> = {
  meat: 'Meat',
  wood: 'Wood',
  coal: 'Coal',
  iron: 'Iron',
  steel: 'Steel',
  fireCrystal: 'Fire Crystals',
  refinedFireCrystal: 'Refined Fire Crystals',
  fireCrystalShard: 'Fire Crystal Shards',
};

/** Resources Zinman's build-cost discount applies to. */
export const ZINMAN_DISCOUNTED: WhiteoutResource[] = ['meat', 'wood', 'coal', 'iron'];

export type ResourceStock = Partial<Record<WhiteoutResource, number>>;

/** A building that must already be at `level` before this upgrade is allowed. */
export interface Prerequisite {
  slug: string;
  level: string;
}

export interface BuildingLevel {
  /** Level label as the game shows it: "24", "30-2", or "FC 1-2". */
  level: string;
  /** Cumulative building power at this level. */
  power: number;
  /** Base construction time in seconds, before any speed buff. */
  seconds: number;
  cost: ResourceStock;
  prereqs: Prerequisite[];
}

export interface BuildingTable {
  slug: string;
  name: string;
  levels: BuildingLevel[];
}

