/** True when this building's table includes Fire Crystal levels. */
export const hasFireCrystalLevels = (table: BuildingTable) =>
  table.levels.some(l => l.level.startsWith('FC'));

/** Buildings whose FC levels are still missing from the scraped data. */
export const buildingsMissingFireCrystal = (tables: BuildingTable[]) =>
  tables.filter(t => !hasFireCrystalLevels(t)).map(t => t.name);
